    dp = [[[0, 0] for _ in range(N)] for _ in range(N)]

    # Populate the dynamic programming table
    for value in grid_values:
        x, y, v = value
        dp[x][y] = [v, v]

    # Fill in the table
    for i in range(N):
        for j in range(N):
            if i > 0 and j > 0:
                dp[i][j][0] = max(dp[i - 1][j][0], dp[i][j - 1][0])
                dp[i][j][1] = max(dp[i - 1][j][1], dp[i][j - 1][1])

    # Find the maximum value
    max_value = 0
    for i in range(N):
        for j in range(N):
            max_value = max(max_value, dp[i][j][0] + dp[i][j][1])

