def count_passing_ways(n: int, m: int) -> int:
    # Initialize a two-dimensional array to store the dynamic programming states
    dp = [[0] * (2 * (n - 1)) for _ in range(m + 1)]

    # Initialize the base case: for one pass, there is only one way to do it
    # (passing the ball to the next student)
    for i in range(n):
        dp[1][i] = 1

    # Fill the dynamic programming table
    for i in range(2, m + 1):
        for j in range(n):
            if j - 1 >= 0:
                dp[i][j] += dp[i - 1][j - 1]
            if j + 1 < n:
                dp[i][j] += dp[i - 1][j + 1]

    # Return the number of passing ways
    return dp[m][0]
