    """
    # Check if the statement contains information about the day of the week
    if any(day in statement for day in days_of_week):
        # If the statement contains information about the day of the week, check if it matches the
        # assumed day of the week
        if "MONDAY" in statement and "TUESDAY" not in statement:
            if "MONDAY" not in statement:
                return False
        elif "TUESDAY" in statement and "MONDAY" not in statement:
            if "TUESDAY" not in statement:
