def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    dp = [[0] * (V + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        for v in range(V + 1):
            if i == 0 or v == 0:
                dp[i][v] = 0
            elif volumes[i - 1] > v:
                dp[i][v] = dp[i - 1][v]
            else:
                dp[i][v] = max(dp[i - 1][v], dp[i - 1][v - volumes[i - 1]] + volumes[i - 1])
    return V - dp[n][V]

