def min_remaining_space(V, n, volumes):
    # Initialize a two-dimensional array dp with all elements set to 0
    dp = [[0 for j in range(V+1)] for i in range(n+1)]

    # Fill in the first row of the array with the volumes of the items
    for i in range(1, n+1):
        dp[i][0] = volumes[i-1]

    # Fill in the first column of the array with the total capacity of the box
    for j in range(1, V+1):
        dp[0][j] = j

    # Fill in the rest of the array using the recurrence relation
    for i in range(1, n+1):
        for j in range(1, V+1):
            if volumes[i-1] > j:
                dp[i][j] = dp[i-1][j]
            else:
                dp[i][j] = max(dp[i-1][j], dp[i-1][j-volumes[i-1]] + volumes[i-1])

    # Return the last element of the last row of the array
    return dp[n][V]
